{"file_path":"src/parser.js","content":"/**
 * Parse a URI reference into its components according to RFC 3986's generic
 * syntax, as restated by the task: an optional scheme, an optional authority,
 * a path, an optional query and an optional fragment. An absent component is
 * null; an empty one is the empty string, and the two are distinct.
 */

/** Components carrying percent-encodings, checked in this order. */
const CHECK_ORDER = ['path', 'userinfo', 'host', 'query', 'fragment']

export function parseURI(str, lineNum) {
  const uri = {
    scheme: null,
    authority: null,
    path: '',
    query: null,
    fragment: null,
    userinfo: null,
    host: null,
    port: null
  }

  let i = 0

  // Scheme: runs to the first ':' that no '/', '?' or '#' precedes.
  for (let j = 0; j < str.length; j++) {
    const c = str[j]
    if (c === ':') {
      uri.scheme = str.slice(0, j)
      i = j + 1
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  // Authority: introduced by '//', running to the next '/', '?' or '#'.
  if (str[i] === '/' && str[i + 1] === '/') {
    i += 2
    let end = i
    while (end < str.length && !'/?#'.includes(str[end])) end++
    uri.authority = str.slice(i, end)
    i = end
    splitAuthority(uri)
  }

  // Path: up to the next '?' or '#'.
  let end = i
  while (end < str.length && str[end] !== '?' && str[end] !== '#') end++
  uri.path = str.slice(i, end)
  i = end

  // Query: from '?' to the next '#'.
  if (str[i] === '?') {
    i++
    let qEnd = i
    while (qEnd < str.length && str[qEnd] !== '#') qEnd++
    uri.query = str.slice(i, qEnd)
    i = qEnd
  }

  // Fragment: from '#' to the end.
  if (str[i] === '#') {
    uri.fragment = str.slice(i + 1)
  }

  for (const name of CHECK_ORDER) {
    const value = uri[name]
    if (value !== null) checkPercentEncodings(value, name, lineNum)
  }

  return uri
}

/**
 * Split an authority into userinfo (before the last '@'), port (after the
 * first ':' that follows the last ']') and the host in between.
 */
function splitAuthority(uri) {
  const auth = uri.authority
  const at = auth.lastIndexOf('@')
  let rest = auth
  if (at !== -1) {
    uri.userinfo = auth.slice(0, at)
    rest = auth.slice(at + 1)
  }

  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  if (colon !== -1) {
    uri.host = rest.slice(0, colon)
    uri.port = rest.slice(colon + 1)
  } else {
    uri.host = rest
  }
}

function checkPercentEncodings(value, name, lineNum) {
  for (let i = 0; i < value.length; i++) {
    if (value[i] !== '%') continue
    const hex = value.slice(i + 1, i + 3)
    if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
      const err = new Error(
        `error: line ${lineNum}: the ${name} has a truncated percent-encoding`
      )
      err.exitCode = 2
      throw err
    }
    i += 2
  }
}
"}

