{"file_path":"src/normalizer.js","content":"/**
 * Normalize a parsed URI and render it back to text.
 */

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21'
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
const ASCII_UPPER = /[A-Z]/g
const ASCII_LOWER = /[a-z]/g

function asciiLower(s) {
  return s.replace(ASCII_UPPER, c => String.fromCharCode(c.charCodeAt(0) + 32))
}

export function normalizeURI(uri) {
  const out = { ...uri }

  // Scheme, ASCII-lowercased.
  if (out.scheme !== null) out.scheme = asciiLower(out.scheme)

  // Percent-encodings in every component.
  if (out.userinfo !== null) out.userinfo = normalizePercent(out.userinfo)
  if (out.host !== null) out.host = normalizePercent(out.host)
  out.path = normalizePercent(out.path)
  if (out.query !== null) out.query = normalizePercent(out.query)
  if (out.fragment !== null) out.fragment = normalizePercent(out.fragment)

  // Host, ASCII-lowercased; the userinfo is left alone.
  if (out.host !== null) out.host = asciiLower(out.host)

  // An empty port, or one written with the digits of the scheme's default.
  if (out.port !== null) {
    if (out.port === '' || out.port === DEFAULT_PORTS[out.scheme]) out.port = null
  }

  out.path = removeDotSegments(out.path)

  if (out.authority !== null && out.path === '') out.path = '/'

  return render(out)
}

function normalizePercent(value) {
  let result = ''
  for (let i = 0; i < value.length; i++) {
    if (value[i] === '%' && i + 2 < value.length) {
      const hex = value.slice(i + 1, i + 3).toUpperCase()
      const char = String.fromCharCode(parseInt(hex, 16))
      result += UNRESERVED.test(char) ? char : '%' + hex
      i += 2
    } else {
      result += value[i]
    }
  }
  return result
}

/** RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '/..') {
      input = '/'
      output = output.slice(0, Math.max(0, output.lastIndexOf('/')))
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let end = input.startsWith('/') ? input.indexOf('/', 1) : input.indexOf('/')
      if (end === -1) end = input.length
      output += input.slice(0, end)
      input = input.slice(end)
    }
  }

  return output
}

function render(uri) {
  let result = ''

  if (uri.scheme !== null) result += uri.scheme + ':'

  if (uri.authority !== null) {
    result += '//'
    if (uri.userinfo !== null) result += uri.userinfo + '@'
    if (uri.host !== null) result += uri.host
    if (uri.port !== null) result += ':' + uri.port
  }

  result += uri.path

  if (uri.query !== null) result += '?' + uri.query
  if (uri.fragment !== null) result += '#' + uri.fragment

  return result
}
"}

