/**
 * Normalize a URI according to RFC 3986 normalization rules.
 */

const defaultPorts = {
  'http': 80,
  'https': 443,
  'ws': 80,
  'wss': 443,
  'ftp': 21
}

const unreservedChars = /^[A-Za-z0-9\-._~]$/

export function normalizeURI(uri) {
  const normalized = { ...uri }

  // 1. Lowercase the scheme (ASCII only)
  if (normalized.scheme) {
    normalized.scheme = normalized.scheme.toLowerCase()
  }

  // 2. Normalize percent-encodings in every component
  if (normalized.userinfo) {
    normalized.userinfo = normalizePercentEncodings(normalized.userinfo)
  }
  if (normalized.host) {
    normalized.host = normalizePercentEncodings(normalized.host)
  }
  normalized.path = normalizePercentEncodings(normalized.path)
  if (normalized.query !== null) {
    normalized.query = normalizePercentEncodings(normalized.query)
  }
  if (normalized.fragment !== null) {
    normalized.fragment = normalizePercentEncodings(normalized.fragment)
  }

  // 3. Lowercase the host (ASCII only, leave userinfo)
  if (normalized.host) {
    normalized.host = normalized.host.toLowerCase()
  }

  // 4. Drop default port or empty port
  if (normalized.port) {
    // Drop empty port
    if (normalized.port === '') {
      normalized.port = null
    } else {
      // Drop default port
      const defaultPort = defaultPorts[normalized.scheme]
      if (defaultPort && normalized.port === defaultPort.toString()) {
        normalized.port = null
      }
    }
  }

  // 5. Remove dot segments from path
  normalized.path = removeDotSegments(normalized.path)

  // 6. When authority is present and path is empty, make path /
  if (normalized.authority && normalized.path === '') {
    normalized.path = '/'
  }

  // Reconstruct the URI
  return reconstructURI(normalized)
}

function normalizePercentEncodings(component) {
  let result = ''
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%' && i + 2 < component.length) {
      const hex = component.substring(i + 1, i + 3)
      const charCode = parseInt(hex, 16)
      const char = String.fromCharCode(charCode)

      // If it's an unreserved character, decode it
      if (unreservedChars.test(char)) {
        result += char
      } else {
        // Otherwise uppercase the hex digits
        result += '%' + hex.toUpperCase()
      }
      i += 2
    } else {
      result += component[i]
    }
  }
  return result
}

function removeDotSegments(path) {
  // RFC 3986 section 5.2.4
  let input = path
  const output = []

  while (input.length > 0) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (input.startsWith('../')) {
      input = input.substring(3)
    } else if (input.startsWith('./')) {
      input = input.substring(2)
    }
    // B: If the input buffer begins with a prefix of "/./" or "/."
    else if (input.startsWith('/./')) {
      input = '/' + input.substring(3)
    } else if (input === '/.') {
      input = '/'
    }
    // C: If the input buffer begins with a prefix of "/../" or "/.."
    else if (input.startsWith('/../')) {
      input = '/' + input.substring(4)
      if (output.length > 0) {
        output.pop()
      }
    } else if (input === '/..') {
      input = '/'
      if (output.length > 0) {
        output.pop()
      }
    }
    // D: If the input buffer consists only of "." or ".."
    else if (input === '.' || input === '..') {
      input = ''
    }
    // E: Move the first path segment to output buffer
    else {
      let segmentEnd
      if (input.startsWith('/')) {
        segmentEnd = input.indexOf('/', 1)
        if (segmentEnd === -1) {
          segmentEnd = input.length
        }
      } else {
        segmentEnd = input.indexOf('/')
        if (segmentEnd === -1) {
          segmentEnd = input.length
        }
      }
      output.push(input.substring(0, segmentEnd))
      input = input.substring(segmentEnd)
    }
  }

  return output.join('')
}

