    result += '//'
    if (uri.userinfo) {
      result += uri.userinfo + '@'
    }
    result += uri.host
    if (uri.port) {
      result += ':' + uri.port
    }
  }

  result += uri.path

  if (uri.query !== null) {
    result += '?' + uri.query
  }

  if (uri.fragment !== null) {
    result += '#' + uri.fragment
  }

  return result
}

