{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Nothing reaches standard output unless
 * every record succeeds.
 */

import { parseURI } from './parser.js'
import { normalizeURI } from './normalizer.js'
import { resolveURI } from './resolver.js'
import { readStdin } from './stdin.js'

function fail(message) {
  const err = new Error(message)
  err.exitCode = 2
  return err
}

function processLine(mode, line, lineNum) {
  if (mode === 'normalize') {
    return normalizeURI(parseURI(line, lineNum))
  }

  const space = line.indexOf(' ')
  if (space === -1) {
    throw fail(`error: line ${lineNum}: expected a base and a reference`)
  }

  const base = parseURI(line.slice(0, space), lineNum)
  if (base.scheme === null) {
    throw fail(`error: line ${lineNum}: the base has no scheme`)
  }

  const ref = parseURI(line.slice(space + 1), lineNum)
  return normalizeURI(resolveURI(base, ref))
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exitCode = 2
    return
  }
  const mode = args[0]

  const input = await readStdin()
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const output = []
  for (let i = 0; i < lines.length; i++) {
    let result
    try {
      result = processLine(mode, lines[i], i + 1)
    } catch (err) {
      if (err.exitCode === 2) {
        process.stderr.write(err.message + '\n')
        process.exitCode = 2
        return
      }
      throw err
    }
    output.push(result)
  }

  if (output.length > 0) process.stdout.write(output.join('\n') + '\n')
}

main().catch(err => {
